{{(async () => {
  const m = BoOrderPhone.model || {};
  const a = m.action;
  if (a === 'close') { return closeModal('BoOrderPhoneModal'); }
  if (!['sync', 'search', 'add', 'remove', 'create'].includes(a)) { return; }
  const en = appsmith.store.bo_lang === 'en';
  const v = m.v || {};
  const str = (x) => String(x == null ? '' : x);
  // What was typed on the phone goes into the form's own fields first; from there on the order is priced,
  // checked and created by the form's own code, the same as on a computer.
  const push = () => Promise.all([
    RecipientNameInput.setValue(str(v.name)), RecipientPhoneInput.setValue(str(v.phone)), CustomerEmailInput.setValue(str(v.email)),
    DeliveryNotesInput.setValue(str(v.notes)), NewAmountInput.setValue(str(v.amount)), DeclaredValueInput.setValue(str(v.declaredValue)),
    NewPickupAddressInput.setValue(str(v.pickup)), NewDropoffAddressInput.setValue(str(v.dropoff)), NewDropoffPostcodeInput.setValue(str(v.zip)),
    OrderShippingSelect.setSelectedOption(str(v.service)), NewPaymentMethodSelect.setSelectedOption(str(v.payer) || 'all'),
    DeclaredValueSelect.setSelectedOption(v.declared === 'yes' ? 'yes' : 'no'), TwoWayCheckbox.setValue(v.twoWay === true),
    ScheduledDeliveryPicker.setValue(v.date ? moment(str(v.date), 'YYYY-MM-DD').startOf('day').toISOString() : ''),
  ]);
  if (a === 'remove') {
    const currentIndex = Number(m.index);
    return ((() => {
         const items = appsmith.store.newOrderItems || [];
         items.splice(currentIndex, 1);
         storeValue('newOrderItems', items).then(() => OrderShippingSelect.selectedOptionValue ? PortalQuote.run() : null);
       })());
  }
  await push();
  if (a === 'sync') {
    ((() => {
     // Typing invalidates whatever was found for the previous text. The search itself
     // is the "Търси" button beside this field (or Enter) - see 2026-09-19.
     // The warehouse's own line needs no search - it is where we collect from.
     const w = (BoWarehouse.data || [])[0];
     if (w && w.address && NewPickupAddressInput.text === w.address) {
       NewPickupLatHidden.setValue(String(w.lat));
       NewPickupLngHidden.setValue(String(w.lng));
       return;
     }
     // Only when the text really differs from what the pin was found for: this handler can
     // fire after a quick search and must not wipe its result (2026-10-02).
     const typed = (NewPickupAddressInput.text || "").trim();
     if ((NewPickupLatHidden.text || NewPickupLngHidden.text) && typed !== (appsmith.store.newPickupSearchedText || "")) {
       NewPickupLatHidden.setValue("");
       NewPickupLngHidden.setValue("");
     }
   })());
    ((() => {
     // Typing invalidates whatever was found for the previous text. The search itself
     // is the "Търси" button beside this field (or Enter) - see 2026-09-19.
     // Only when the text really differs from what the pin was found for: this handler can
     // fire after a quick search and must not wipe its result (2026-10-02).
     const typed = (NewDropoffAddressInput.text || "").trim();
     if ((NewDropoffLatHidden.text || NewDropoffLngHidden.text) && typed !== (appsmith.store.newDropoffSearchedText || "")) {
       NewDropoffLatHidden.setValue("");
       NewDropoffLngHidden.setValue("");
     }
   })());
    ((() => {
     // The pin was found for one address + postcode; a different postcode means another
     // search is needed - the same rule as the address box (2026-10-04).
     const zip = (NewDropoffPostcodeInput.text || "").trim();
     if ((NewDropoffLatHidden.text || NewDropoffLngHidden.text) && zip !== (appsmith.store.newDropoffSearchedZip || "")) {
       NewDropoffLatHidden.setValue("");
       NewDropoffLngHidden.setValue("");
     }
   })());
    if (m.quote) { return (OrderShippingSelect.selectedOptionValue ? PortalQuote.run() : null); }
    return;
  }
  if (a === 'search') {
    if (m.which === 'pickup') { return ((() => {
     const address = (NewPickupAddressInput.text || "").trim();
     if (address.length < 4) {
       showAlert("Въведете адрес преди да търсите", "warning");
       return;
     }
     GeocodeNewPickupAddress.run()
       .then(() => {
         if (GeocodeNewPickupAddress.data?.results?.length > 0) {
           LocationManager.updateNewPickupFromGeocode();
         } else {
           showAlert("Адресът не е намерен — проверете изписването", "warning");
         }
       })
       .catch(() => showAlert("Търсенето на адреса не мина. Опитайте пак.", "error"));
   })()); }
    return (LocationManager.searchNewDropoff());
  }
  if (a === 'add') {
    const i = m.item || {};
    await Promise.all([
      ItemNameInput.setValue(str(i.name)), ItemSkuInput.setValue(str(i.sku)), ItemQuantityInput.setValue(str(i.qty) || '1'),
      ItemWeightInput.setValue(str(i.weight)), ItemLengthInput.setValue(str(i.length)), ItemWidthInput.setValue(str(i.width)), ItemHeightInput.setValue(str(i.height)),
    ]);
    return ((() => {
     if (!ItemNameInput.text ) {
       showAlert("Въведете име на артикул", "error");
       return;
     }

     // Weight and L×W×H per unit are required (Ico, 2026-10-02): the товарителница sums
     // them, and the console shows them on every product line. Comma or point both work.
     const num = (w) => { const v = Number(String(w.text || "").trim().replace(",", ".")); return v > 0 ? v : null; };
     const weight = num(ItemWeightInput), length = num(ItemLengthInput), width = num(ItemWidthInput), height = num(ItemHeightInput);
     if (weight === null || length === null || width === null || height === null) {
       showAlert("Въведете тегло (кг) и размери (см) на артикула - дължина, ширина и височина", "error");
       return;
     }

     // What one parcel may be (BUSINESS.md: 90×90×90 cm, 20 kg). Anything bigger is a
     // phone call, not an order (Ico, 2026-10-06): the office checks whether it can be
     // taken and at what price. The server refuses the same way, so the Excel upload
     // cannot slip one through either.
     // 20 kg for everybody, unless the office agreed another limit with this client (BoExtras, read
     // when the form opens - XBORN's robot vacuums, 2026-11-17). The server holds the same figure.
     const OWN_KG = Number((BoExtras.data || {}).max_parcel_kg);
     const MAX_KG = OWN_KG > 20 ? OWN_KG : 20, MAX_CM = 90;
     if (weight > MAX_KG || length > MAX_CM || width > MAX_CM || height > MAX_CM) {
       showAlert(appsmith.store.bo_lang === 'en'
         ? "This parcel is over our maximum size of 90×90×90 cm and " + MAX_KG + " kg. Please call us on +359 88 286 8723 so we can check whether we can take it."
         : "Пратката надвишава максималните размери 90×90×90 см и " + MAX_KG + " кг. Обадете ни се на +359 88 286 8723, за да проверим дали можем да я вземем.", "error");
       return;
     }

     const currentItems = appsmith.store.newOrderItems || [];
     const newItem = {
       name: ItemNameInput.text,
       sku: ItemSkuInput.text || "",
       quantity: parseInt(ItemQuantityInput.text) || 1,
       weight_kg: weight,
       length_cm: length,
       width_cm: width,
       height_cm: height
     };

     // The preview follows the weights: a service priced by weight changes with them (TODO 50).
     storeValue('newOrderItems', [...currentItems, newItem]).then(() => OrderShippingSelect.selectedOptionValue ? PortalQuote.run() : null);

     // Clear inputs
     ItemNameInput.setValue('');
     ItemSkuInput.setValue('');
     ItemQuantityInput.setValue('1');
     ItemWeightInput.setValue('');
     ItemLengthInput.setValue('');
     ItemWidthInput.setValue('');
     ItemHeightInput.setValue('');

     showAlert("Артикулът е добавен", "success");
   })());
  }
  // 'create'. Never from anything but what the phone shows: if a field did not take the value, stop.
  const same = (x, y) => str(x).trim() === str(y).trim();
  const day = ScheduledDeliveryPicker.selectedDate ? moment(ScheduledDeliveryPicker.selectedDate).format('YYYY-MM-DD') : '';
  if (!same(RecipientNameInput.text, v.name) || !same(RecipientPhoneInput.text, v.phone) || !same(CustomerEmailInput.text, v.email)
      || !same(DeliveryNotesInput.text, v.notes) || !same(NewAmountInput.text, v.amount) || !same(DeclaredValueInput.text, v.declaredValue)
      || !same(NewPickupAddressInput.text, v.pickup) || !same(NewDropoffAddressInput.text, v.dropoff) || !same(NewDropoffPostcodeInput.text, v.zip)
      || !same(OrderShippingSelect.selectedOptionValue, v.service) || !same(NewPaymentMethodSelect.selectedOptionValue, str(v.payer) || 'all')
      || !same(DeclaredValueSelect.selectedOptionValue, v.declared === 'yes' ? 'yes' : 'no') || (TwoWayCheckbox.isChecked === true) !== (v.twoWay === true)
      || day !== str(v.date)) {
    showAlert(en ? 'The form could not pass on what you typed. Please press the button again.' : 'Формата не успя да предаде въведеното. Моля, натиснете бутона отново.', 'error');
    return;
  }
  return ((() => {
      // Use LocationManager validation
      const validation = LocationManager.validateOrderForm();

      if (!validation.isValid) {
          showAlert("Моля, поправете следното:\n" + validation.errors.join("\n"), "error");
          return;
      }

      // Validate service rate selection
      if (!OrderShippingSelect.selectedOptionValue) {
          showAlert("Изберете вид доставка", "error");
          return;
      }

      // The COD amount is optional (Ico, 2026-10-04): none typed = no наложен платеж and no
      // НП fee; the delivery and any declared value still apply. Nothing is asked for here.

      if (DeclaredValueSelect.selectedOptionValue === 'yes') {
          const dv = Number(String(DeclaredValueInput.text || '').trim().replace(',', '.'));
          if (!(dv > 0 && dv <= 5112.92)) {
              showAlert("Въведете обявена стойност до 5 112,92 € (раздел Плащане)", "error");
              return;
          }
      }

      // At least one product, each with weight and size (Ico, 2026-10-02). An item added
      // before this rule has none - the merchant removes it and adds it again.
      const items = appsmith.store.newOrderItems || [];
      if (items.length === 0) {
          showAlert("Добавете поне един артикул с тегло и размери (раздел Артикули)", "error");
          return;
      }
      const unmeasured = items.find((i) => !(i.weight_kg > 0 && i.length_cm > 0 && i.width_cm > 0 && i.height_cm > 0));
      if (unmeasured) {
          showAlert("Артикулът „" + unmeasured.name + "“ няма тегло и размери. Изтрийте го и го добавете отново с тях.", "error");
          return;
      }

      // Standard from tomorrow on, Express from now on, never the past (Ico, 2026-10-02).
      // Checked here so the merchant reads it before anything is sent; the request body
      // and the server apply the same rule. Since 2026-10-06 the picker is a DAY, so this
      // compares days: "today" means "from now" (CreateOrderAPI sends it as no date). The
      // old check compared the day's midnight with "now minus 15 minutes", so from 00:15
      // on, every Express order for today was refused as "in the past" (TheBasket, 2026-10-08).
      const day = ScheduledDeliveryPicker.selectedDate ? moment(ScheduledDeliveryPicker.selectedDate).startOf("day") : null;
      const isExpress = /express/i.test(OrderShippingSelect.selectedOptionLabel || "");
      if (day && day.isBefore(moment().startOf("day"))) {
          showAlert("Датата на доставка е в миналото. Изберете днес или по-късно.", "error");
          return;
      }
      if (day && !isExpress && day.isBefore(moment().add(1, "days").startOf("day"))) {
          showAlert("Стандартната доставка е от утре нататък. За доставка днес изберете Експресна.", "error");
          return;
      }

      showAlert("Създаваме поръчката...", "info");

      // One call now. The delivery quote used to be made here first, by two SQL
      // queries writing straight into the production database - and they reused a
      // single quote row for every order placed on the same rate within a day, then
      // never linked it to the order. Fulfilya builds the quote as it creates the
      // order, the same way it does for orders arriving from a shop.
      CreateOrderAPI.run()
          .then((result) => {
              const orderId = result.order_id || "";

              // Our fees on the order, straight away (Ico, 2026-10-02) - the same figures the
              // console box and Детайли show.
              const f = result.fees || (CreateOrderAPI.data || {}).fees || null;
              const eur = (v) => Number(v || 0).toLocaleString('bg-BG', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
              let feesLine = '';
              if (f) {
                  const dvf = Number(f.declared_fee) > 0 ? ` · обявена стойност ${eur(f.declared_fee)}` : '';
                  // One НП rate for cash, another for card (2026-10-07): settled when the driver records how the recipient paid.
                  const fee = f.cod_fee_card !== undefined && Number(f.cod_fee_card) !== Number(f.cod_fee)
                      ? `${eur(f.cod_fee)} в брой / ${eur(f.cod_fee_card)} с карта`
                      : eur(f.cod_fee);
                  feesLine = Number(f.collected) > 0
                      ? `\nСума за събиране ${eur(f.collected)} · доставка ${eur(f.delivery)} · такса НП ${fee}${dvf}`
                      : `\nШофьорът не събира нищо · за фактуриране ${eur(f.invoiced)} (доставка ${eur(f.delivery)}${dvf})`;
              }
              showAlert(`Поръчката е създадена${feesLine}`, "success");

              // Reset form using LocationManager
              LocationManager.resetOrderForm();

              closeModal('BoOrderPhoneModal');

              // Refresh all dashboard data
              GetOrdersList.run();
              // The Табло tiles too - they kept the old count until a page reload
              // (found in testing, 2026-10-01).
              BoStats.run();
              BoPayment.run();
              BoStatus.run();
              BoDays.run();
          })
          .catch(err => {
              console.error("Order creation failed:", err, CreateOrderAPI.data, CreateOrderAPI.responseMeta);
              // Fulfilya answers a refused order with a sentence written for a merchant
              // to read, in the response body. err.message is only Appsmith's generic
              // "CreateOrderAPI failed to execute", so read the body first.
              // A login the server no longer knows: the merchant kept yesterday's session
              // and its token was gone, so every order came back "Unauthenticated" while
              // the Табло (read straight from the database) looked fine (TheBasket,
              // 2026-10-02). Say so in their words and take them to the login page.
              const code = Number((CreateOrderAPI.responseMeta || {}).statusCode || 0);
              if (code === 401 || /unauthenticated/i.test(JSON.stringify(CreateOrderAPI.data || ""))) {
                  showAlert("Сесията ви изтече. Влезте отново и създайте поръчката пак.", "warning");
                  closeModal('BoOrderPhoneModal');
                  AuthManager.logout();
                  return;
              }
              const body = CreateOrderAPI.data || {};
              const firstField = body.errors ? Object.values(body.errors).flat()[0] : null;
              const reason = body.error || firstField || body.message || err.message || "Please check your input and try again";
              showAlert("Поръчката не беше създадена: " + reason, "error");
          });
  })());
})()}}

